/* ── CLI thread ───────────────────────────────────────────────── */

/* Read one line directly from fd 0.
 *
 * fgets(stdin) cannot be used here: NSH leaves the console in raw mode, so
 * Enter arrives as '\r' and never as '\n' — fgets() would block forever even
 * though bytes are being delivered.  Reading the raw fd and accepting both
 * '\r' and '\n' as the line terminator works regardless of the termios state.
 *
 * Returns the line length (may be 0 for an empty line) or -1 on a fatal error.
 */

static int cli_read_line(char* line, int maxlen)
{
    int lp = 0;

    for (;;)
    {
        char c;
        ssize_t nr = read(STDIN_FILENO, &c, 1);
        if (nr < 0)
        {
            if (errno == EINTR)
                continue;
            usleep(20 * 1000); /* EAGAIN: nothing buffered yet */
            continue;
        }
        if (nr == 0)
        {
            usleep(20 * 1000);
            continue;
        }

        if (g_cli_verbose)
            syslog(LOG_INFO, "[%s] rx 0x%02x ('%c')\n", TAG,
                (unsigned char)c, (c >= 0x20 && c < 0x7f) ? c : '.');

        if (c == '\r' || c == '\n')
        {
            line[lp] = '\0';
            return lp;
        }

        if (lp < maxlen - 1)
            line[lp++] = c;
    }
}

static void* cli_thread(void* arg)
{
    (void)arg;
    char line[LINE_LEN];
    char* argv[MAX_ARGS];

    syslog(LOG_INFO, "[%s] NSH CLI started. Type 'help' for commands.\n", TAG);
    pthread_mutex_lock(&g_stdout_lock);
    printf("vela> ");
    fflush(stdout);
    pthread_mutex_unlock(&g_stdout_lock);
    syslog(LOG_INFO, "[%s] prompt printed, entering read loop\n", TAG);

    while (cli_read_line(line, sizeof(line)) >= 0) {
        /* Strip trailing newline */
        size_t len = strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';

        if (len == 0) {
            pthread_mutex_lock(&g_stdout_lock);
            printf("vela> ");
            fflush(stdout);
            pthread_mutex_unlock(&g_stdout_lock);
            continue;
        }

        int argc = tokenise(line, argv, MAX_ARGS);
        if (argc == 0) {
            pthread_mutex_lock(&g_stdout_lock);
            printf("vela> ");
            fflush(stdout);
            pthread_mutex_unlock(&g_stdout_lock);
            continue;
        }

        const char* cmd = argv[0];
