/****************************************************************************
 * Name: esp_hr_timer_init
 *
 * Description:
 *   Initialize the timer adapter and the underlying ESP timer subsystem.
 *
 * Input Parameters:
 *   None.
 *
 * Returned Value:
 *   OK on success; ERROR on failure.
 *
 ****************************************************************************/

int esp_hr_timer_init(void)
{
  esp_err_t ret;

  if (g_hr_timer_initialized)
    {
      return OK;
    }

  /* Initialize the timer subsystem.  esp_timer_early_init() primes the
   * systimer HAL (systimer_hal_init) - it is normally run from the
   * ESP_SYSTEM_INIT_FN startup table which is not executed on this port;
   * without it systimer_hal.dev stays NULL and the alarm-enable path
   * faults (write to 0x64). */

  esp_timer_early_init();
  ret = esp_timer_init();
  if (ret == ESP_OK)
    {
      g_hr_timer_initialized = true;
      return OK;
    }

  return ERROR;
}
